// src/lib/credit-subgrades.ts
function normalizeGrade(value) {
  return String(value ?? "").replace(/[۰-۹]/g, (d) => String(PERSIAN_DIGITS.indexOf(d))).replace(/[٠-٩]/g, (d) => String(ARABIC_DIGITS.indexOf(d))).replace(/\s+/g, "").toUpperCase();
}
function expandRankList(values) {
  const out = [];
  const push2 = (v) => {
    if (!out.includes(v)) out.push(v);
  };
  for (const raw2 of values) {
    const v = normalizeGrade(raw2);
    if (!v) continue;
    if (/^[A-E]$/.test(v)) for (const n of [1, 2, 3]) push2(`${v}${n}`);
    else push2(v);
  }
  return out;
}
function compactRankList(values) {
  const list2 = expandRankList(values);
  const out = [];
  for (const v of list2) {
    const letter = /^[A-E][1-3]$/.test(v) ? v[0] : "";
    if (letter && [1, 2, 3].every((n) => list2.includes(`${letter}${n}`))) {
      if (!out.includes(letter)) out.push(letter);
    } else out.push(v);
  }
  return out;
}
function gradeMatches(value, permitted4) {
  const v = normalizeGrade(value);
  if (!v) return false;
  const allowed = expandRankList(permitted4);
  if (/^[A-E]$/.test(v)) return allowed.some((p) => p === v || p.length === 2 && p[0] === v && /^[1-3]$/.test(p[1]));
  return allowed.includes(v);
}
function parseStoredRanks(raw2) {
  if (raw2 == null) return [];
  if (Array.isArray(raw2)) return raw2.map(String).map((s) => s.trim()).filter(Boolean);
  const text3 = String(raw2).trim();
  if (!text3) return [];
  try {
    const parsed2 = JSON.parse(text3);
    if (Array.isArray(parsed2)) return parsed2.map(String).map((s) => s.trim()).filter(Boolean);
  } catch {
  }
  return text3.split(/[,،]/).map((s) => s.replace(/[[\]"]/g, "").trim()).filter(Boolean);
}
function compactRankJson(raw2) {
  if (raw2 == null || raw2 === "") return raw2;
  const list2 = parseStoredRanks(raw2);
  if (!list2.length) return raw2;
  const compact2 = compactRankList(list2);
  if (compact2.length === list2.length && compact2.every((v, i) => v === list2[i])) return raw2;
  return JSON.stringify(compact2);
}
