      menuTrack: "\u067E\u06CC\u06AF\u06CC\u0631\u06CC \u067E\u0631\u0648\u0646\u062F\u0647\u200C\u06CC \u062A\u0633\u0647\u06CC\u0644\u0627\u062A",
