  if (queryRow("SELECT 1 FROM goods_credit_lots WHERE application_id=?", [applicationId])) throw new Error("application_credit_requires_reconciliation");
  execute("INSERT OR IGNORE INTO goods_plan_wallets(customer_id,plan_id,balance_toman) VALUES(?,?,'0')", [customerId3, app2.plan_id]);
  const w = queryRow("SELECT * FROM goods_plan_wallets WHERE customer_id=? AND plan_id=?", [customerId3, app2.plan_id]);
  execute("INSERT INTO goods_credit_lots(ledger_id,wallet_id,application_id,amount_toman,principal_toman) VALUES(?,?,?,?,?)", [ledgerId, w.id, applicationId, amount3, money(app2.approved_amount ?? app2.requested_amount).toString()]);
