    const parsed2 = items2.map((i) => {
      const title = String(i.title ?? "").trim(), quantity = Number(i.quantity);
      if (!title || title.length > 250 || !Number.isSafeInteger(quantity) || quantity < 1 || quantity > 1e6) throw new Error("invalid_invoice_items");
      const unit = money(i.unitPriceToman);
      if (!unit) throw new Error("invalid_invoice_items");
      return { title, quantity, unit, total: unit * BigInt(quantity) };
    });
    if (parsed2.reduce((s, i) => s + i.total, 0n) !== money(p.credit_amount_toman)) throw new Error("invoice_total_must_equal_credit");
    executeChanges("DELETE FROM goods_invoice_items WHERE purchase_id=?", [id5]);
    for (const i of parsed2) execute("INSERT INTO goods_invoice_items(purchase_id,title,quantity,unit_price_toman,total_toman) VALUES(?,?,?,?,?)", [id5, i.title, i.quantity, i.unit.toString(), i.total.toString()]);
    executeChanges("UPDATE goods_purchases SET invoice_version=invoice_version+1,invoice_signed_version=NULL WHERE id=?", [id5]);
