      const creditedAt = now3();
      const ledgerId = execute(
        "INSERT INTO wallet_ledger_v2(wallet_id,amount,kind,idempotency_key,actor_user_id,actor_customer_id,created_at) VALUES(?,?,?,?,?,?,?)",
        [
          account.id,
          intent.amount_toman,
          "cash_payment",
          key,
          attempt?.initiated_by_user_id ?? actorId,
          attempt?.initiated_by_customer_id ?? intent.created_by_customer_id ?? null,
          creditedAt
        ]
      );
