  if (loanCaseFinancialTermsLocked(r)) return error(res, 409, "admin_case_financial_terms_locked");
  if (!["guarantor_registration", "guarantor_documents_upload", "guarantor_documents_review"].includes(r.stage) || !canAct(r.stage === "guarantor_documents_review" ? "guarantor_documents_upload" : r.stage, user(res), r.customer_id, r.status)) return error(res, 403, "action_forbidden");
  const b = req.body ?? {};
