var ACC_ASSUMPTION = "\u0627\u0632 \u0631\u0648\u06CC \u062C\u062F\u0648\u0644 \u0628\u0631\u0631\u0633\u06CC \u0635\u062D\u062A \u0627\u0648\u0644\u0648\u06CC\u062A\u200C\u0628\u0646\u062F\u06CC \u062A\u0645\u0627\u0633 \u0627\u0648\u0644 (team_data_accuracy_reviews) \u0645\u062D\u0627\u0633\u0628\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F\u060C \u0646\u0647 \u06CC\u06A9 \u0628\u0627\u0632\u0628\u06CC\u0646\u06CC \u0639\u0645\u0648\u0645\u06CC \u062B\u0628\u062A \u062F\u0631 \u0633\u06CC\u200C\u0622\u0631\u200C\u0627\u0645.";
var FU_ASSUMPTION = "\u067E\u06CC\u06AF\u06CC\u0631\u06CC = \u06CC\u0627\u062F\u0622\u0648\u0631\u0647\u0627 \u0628\u0647\u200C\u0627\u0636\u0627\u0641\u0647\u200C\u06CC \u06A9\u0627\u0631\u0647\u0627\u06CC \u067E\u06CC\u06AF\u06CC\u0631\u06CC \u0648 \u0645\u0648\u0639\u062F \u062F\u0631 \u0628\u0631\u0646\u0627\u0645\u0647\u0654 \u0631\u0648\u0632. \u0628\u0647\u200C\u0645\u0648\u0642\u0639 \u06CC\u0639\u0646\u06CC \u0627\u0646\u062C\u0627\u0645 \u062A\u0627 \u067E\u0627\u06CC\u0627\u0646 \u0647\u0645\u0627\u0646 \u0631\u0648\u0632 \u062A\u0647\u0631\u0627\u0646.";
var ASSIGN_ASSUMPTION = "\u0645\u0634\u062A\u0631\u06CC \u062A\u062E\u0635\u06CC\u0635\u200C\u06CC\u0627\u0641\u062A\u0647 = \u0645\u0634\u062A\u0631\u06CC\u0627\u0646\u06CC \u06A9\u0647 \u062F\u0631 \u0647\u0645\u06CC\u0646 \u062F\u0648\u0631\u0647 \u0628\u0647 \u06A9\u0627\u0631\u0634\u0646\u0627\u0633 \u0645\u0646\u0633\u0648\u0628 \u0634\u062F\u0647\u200C\u0627\u0646\u062F (\u0627\u06CC\u062C\u0627\u062F \u06CC\u0627 \u062A\u063A\u06CC\u06CC\u0631 \u0645\u0627\u0644\u06A9 \u062F\u0631 \u062A\u0627\u0631\u06CC\u062E\u0686\u0647)\u060C \u0646\u0647 \u0645\u0648\u062C\u0648\u062F\u06CC \u06A9\u0644 \u067E\u0631\u0648\u0646\u062F\u0647\u200C\u0647\u0627.";
var AMOUNT_ASSUMPTION = "\u0645\u0628\u0644\u063A \u0641\u0631\u0648\u0634 = \u0645\u0628\u0644\u063A \u0645\u0635\u0648\u0628 \u067E\u0631\u0648\u0646\u062F\u0647\u0654 \u0648\u0627\u0645 \u062F\u0631 \u0632\u0645\u0627\u0646 \u062A\u06A9\u0645\u06CC\u0644. \u062E\u0631\u06CC\u062F \u06A9\u0627\u0644\u0627 \u062F\u0631 \u0627\u06CC\u0646 \u0639\u062F\u062F \u0646\u06CC\u0633\u062A.";
var WORKDAY_ASSUMPTION = "\u0631\u0648\u0632 \u06A9\u0627\u0631\u06CC = \u0631\u0648\u0632\u0647\u0627\u06CC \u062A\u0642\u0648\u06CC\u0645 \u062A\u0647\u0631\u0627\u0646 \u0628\u0647\u200C\u062C\u0632 \u062C\u0645\u0639\u0647 \u0648 \u062A\u0639\u0637\u06CC\u0644\u0627\u062A \u0631\u0633\u0645\u06CC (official_holidays). \u0633\u0627\u0639\u0627\u062A \u062D\u0636\u0648\u0631 \u062F\u0633\u062A\u06AF\u0627\u0647 \u062D\u0636\u0648\u0631 \u0648 \u063A\u06CC\u0627\u0628 \u062F\u0631 \u0627\u06CC\u0646 \u0646\u0633\u062E\u0647 \u0646\u06CC\u0633\u062A.";
var DOC_ASSUMPTION = "\u0648\u0627\u062C\u062F \u0634\u0631\u0627\u06CC\u0637 = \u0627\u0648\u0644\u06CC\u0646 \u0648\u0631\u0648\u062F \u067E\u0631\u0648\u0646\u062F\u0647 \u0628\u0647 \u0645\u0631\u062D\u0644\u0647\u0654 \u0628\u0627\u0631\u06AF\u0630\u0627\u0631\u06CC \u0645\u062F\u0627\u0631\u06A9 \u062F\u0631 \u062F\u0648\u0631\u0647\u061B \u062A\u06A9\u0645\u06CC\u0644 = \u0639\u0628\u0648\u0631 \u0627\u0632 \u0645\u0631\u062D\u0644\u0647\u0654 \u0628\u0631\u0631\u0633\u06CC \u0645\u062F\u0627\u0631\u06A9.";
var CANCEL_ASSUMPTION = "\u06AF\u0631\u0648\u0647: \u067E\u0631\u0648\u0646\u062F\u0647\u200C\u0647\u0627\u06CC \u0648\u0627\u0645 \u063A\u06CC\u0631\u067E\u06CC\u0634\u200C\u062B\u0628\u062A \u06A9\u0647 \u062F\u0631 \u0647\u0645\u06CC\u0646 \u062F\u0648\u0631\u0647 \u0627\u06CC\u062C\u0627\u062F \u0634\u062F\u0647\u200C\u0627\u0646\u062F (\u0647\u0645\u0627\u0646 \u0645\u062E\u0631\u062C). \u0644\u063A\u0648 = \u0627\u0648\u0644\u06CC\u0646 \u0627\u0642\u062F\u0627\u0645 cancel-case \u06CC\u0627 funder-initial-reject \u0631\u0648\u06CC \u0647\u0645\u0627\u0646 \u067E\u0631\u0648\u0646\u062F\u0647 \u062A\u0627 \u067E\u0627\u06CC\u0627\u0646 \u062F\u0648\u0631\u0647. \u0631\u062F \u06A9\u0627\u0631\u0634\u0646\u0627\u0633 \u06CC\u0627 \u0631\u062F \u0645\u062F\u06CC\u0631 \u062F\u0631 \u0627\u06CC\u0646 \u0646\u0631\u062E \u0646\u06CC\u0633\u062A.";
var RETAIN_ASSUMPTION = "\u0641\u0639\u0627\u0644 \u062F\u0631 \u0634\u0631\u0648\u0639 \u062F\u0648\u0631\u0647 = \u0645\u0634\u062A\u0631\u06CC \u0645\u0646\u0633\u0648\u0628 \u06A9\u0647 \u0642\u0628\u0644 \u0627\u0632 \u062F\u0648\u0631\u0647 \u0633\u0627\u062E\u062A\u0647 \u0634\u062F\u0647 \u0648 \u0627\u0644\u0627\u0646 \u0644\u063A\u0648 \u0646\u06CC\u0633\u062A\u060C \u0645\u06AF\u0631 \u0627\u06CC\u0646\u06A9\u0647 \u062F\u0631 \u062F\u0648\u0631\u0647 \u0641\u0639\u0627\u0644\u06CC\u062A \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u062F. \u062A\u0627\u0631\u06CC\u062E \u0644\u063A\u0648 \u062C\u062F\u0627\u06AF\u0627\u0646\u0647 \u062B\u0628\u062A \u0646\u0645\u06CC\u200C\u0634\u0648\u062F.";
var PREV_ASSUMPTION = "\u062E\u0631\u06CC\u062F\u0627\u0631 \u0642\u0628\u0644\u06CC = \u0645\u0634\u062A\u0631\u06CC \u0628\u0627 \u062F\u0633\u062A\u200C\u06A9\u0645 \u06CC\u06A9 \u067E\u0631\u0648\u0646\u062F\u0647\u0654 \u062A\u06A9\u0645\u06CC\u0644\u200C\u0634\u062F\u0647 \u067E\u06CC\u0634 \u0627\u0632 \u0634\u0631\u0648\u0639 \u062F\u0648\u0631\u0647. \u062F\u0631 \u0635\u0648\u0631\u062A \u062A\u0639\u06CC\u06CC\u0646 \u0641\u0627\u0635\u0644\u0647\u0654 \u0631\u0648\u0632\u060C \u0641\u0642\u0637 \u06A9\u0633\u0627\u0646\u06CC \u06A9\u0647 \u0627\u0632 \u062E\u0631\u06CC\u062F\u0634\u0627\u0646 \u0622\u0646 \u0641\u0627\u0635\u0644\u0647 \u06AF\u0630\u0634\u062A\u0647 \u0628\u0627\u0634\u062F.";
var REG_ASSUMPTION = "\u0622\u0645\u0627\u062F\u0647\u0654 \u062A\u062D\u0648\u06CC\u0644 \u0628\u0647 \u0648\u0627\u062D\u062F \u062B\u0628\u062A = \u0627\u0648\u0644\u06CC\u0646 \u0648\u0631\u0648\u062F \u0628\u0647 \u0645\u0631\u062D\u0644\u0647\u0654 \u062A\u062D\u0648\u06CC\u0644 \u0645\u062F\u0627\u0631\u06A9 \u0641\u06CC\u0632\u06CC\u06A9\u06CC\u061B \u062A\u062D\u0648\u06CC\u0644 = \u0627\u0648\u0644\u06CC\u0646 \u0627\u0642\u062F\u0627\u0645 \u0628\u0639\u062F\u06CC \u06CC\u06A9 \u06A9\u0627\u0631\u0628\u0631 \u0628\u0627 \u0646\u0642\u0634 \u062B\u0628\u062A\u200C\u06A9\u0646\u0646\u062F\u0647.";
